// Regenerates `maplibre_expression_fixtures.dart` from a checkout of
// maplibre-style-spec:
//
//   git clone --depth 1 https://github.com/maplibre/maplibre-style-spec.git /tmp/spec
//   dart run test/fixtures/maplibre_expression_fixtures_gen.dart /tmp/spec
//
// Every `test/integration/expression/tests/**/test.json` becomes one line of
// the embedded JSON, keyed by its directory and sorted, so a spec update
// diffs as the fixtures it changed. The data is embedded in a Dart file —
// not read from disk — so the conformance test also runs in the browser,
// where dart2js number semantics are the ones that bite.
import 'dart:convert';
import 'dart:io';

void main(List<String> args) {
  if (args.length != 1) {
    stderr.writeln('usage: dart run $_self <maplibre-style-spec checkout>');
    exit(64);
  }
  final spec = Directory(args.single);
  final tests = Directory('${spec.path}/test/integration/expression/tests');
  final commit = Process.runSync('git', ['-C', spec.path, 'rev-parse', 'HEAD'])
      .stdout
      .toString()
      .trim();
  final entries = <String, String>{};
  for (final file in tests.listSync(recursive: true).whereType<File>()) {
    if (!file.path.endsWith('/test.json')) continue;
    final name = file.parent.path.substring(tests.path.length + 1);
    final json = jsonDecode(file.readAsStringSync());
    entries[name] = jsonEncode(json);
  }
  final names = entries.keys.toList()..sort();
  final body = StringBuffer('{\n');
  for (var i = 0; i < names.length; i++) {
    body
      ..write(jsonEncode(names[i]))
      ..write(':')
      ..write(entries[names[i]])
      ..write(i == names.length - 1 ? '\n' : ',\n');
  }
  body.write('}');
  if (body.toString().contains("'''")) {
    stderr.writeln("a fixture contains ''' — pick another string delimiter");
    exit(1);
  }
  final out = File('${File.fromUri(Platform.script).parent.path}/'
      'maplibre_expression_fixtures.dart');
  out.writeAsStringSync('''
// GENERATED by maplibre_expression_fixtures_gen.dart — do not edit.
//
// The expression test fixtures of maplibre-style-spec
// (test/integration/expression/tests), BSD-3-Clause, Copyright (c) 2020,
// MapLibre contributors — see MAPLIBRE_LICENSE.txt next to this file.

/// The maplibre-style-spec commit these fixtures were taken from.
const maplibreExpressionFixturesCommit =
    '$commit';

/// Fixture name (its directory under `tests/`) → the fixture's JSON.
const maplibreExpressionFixturesJson = r\'\'\'
$body\'\'\';
''');
  stdout.writeln('wrote ${names.length} fixtures to ${out.path}');
}

const _self = 'test/fixtures/maplibre_expression_fixtures_gen.dart';
